import { Download } from "lucide-react";
import { db } from "@/lib/db";
import { formatINR } from "@/lib/money";
import { cn, formatDate } from "@/lib/utils";
import { PageHeader, Table, td } from "@/components/admin/ui";

export default async function AdminCustomers({ searchParams }: PageProps<"/admin/customers">) {
  const sp = await searchParams;
  const q = typeof sp.q === "string" ? sp.q.trim() : "";
  const users = await db.user.findMany({
    where: { role: "CUSTOMER", ...(q ? { OR: [{ name: { contains: q, mode: "insensitive" } }, { email: { contains: q, mode: "insensitive" } }, { phone: { contains: q } }] } : {}) },
    include: { orders: { where: { paidAt: { not: null }, status: { notIn: ["CANCELLED", "REFUNDED"] } }, select: { total: true, createdAt: true } } },
    orderBy: { createdAt: "desc" },
    take: 500,
  });
  const rows = users
    .map((u) => ({ ...u, ltv: u.orders.reduce((s, o) => s + o.total, 0), last: u.orders.map((o) => o.createdAt).sort((a, b) => +b - +a)[0] }))
    .sort((a, b) => b.ltv - a.ltv);
  const repeat = rows.filter((r) => r.orders.length > 1).length;
  const buyers = rows.filter((r) => r.orders.length > 0).length;

  return (
    <>
      <PageHeader
        title="Customers"
        description={`${rows.length} customers · ${buyers} have purchased · repeat purchase rate ${buyers ? ((repeat / buyers) * 100).toFixed(1) : 0}%`}
        actions={<a href="/api/admin/export?type=customers" className="btn-outline"><Download className="h-4 w-4" /> Export CSV</a>}
      />
      <form className="mb-4 flex gap-2"><input name="q" defaultValue={q} placeholder="Name, email or phone" className="input max-w-xs" /><button className="btn-dark">Search</button></form>
      <div className="rounded-lg border border-line bg-white">
        <Table head={["Customer", "Phone", "Joined", "Orders", "Lifetime value", "Last order"]}>
          {rows.map((u) => (
            <tr key={u.id}>
              <td className={td}><p className="font-medium">{u.name}</p><p className="text-xs text-muted">{u.email}</p></td>
              <td className={td}>{u.phone}</td>
              <td className={cn(td, "text-muted")}>{formatDate(u.createdAt)}</td>
              <td className={cn(td, "tabular-nums")}>{u.orders.length}</td>
              <td className={cn(td, "font-medium tabular-nums")}>{formatINR(u.ltv)}</td>
              <td className={cn(td, "text-muted")}>{u.last ? formatDate(u.last) : "—"}</td>
            </tr>
          ))}
        </Table>
      </div>
    </>
  );
}
